use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use actix_multipart::Multipart;
use futures_util::StreamExt;
use std::path::{Path, PathBuf};
use std::io::Write;
use uuid::Uuid;
use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

const UPLOAD_ROOT: &str = "/var/uploads";
const HMAC_SECRET: &[u8] = b"tenant-isolation-key-2024";

#[derive(Clone)]
struct TenantContext {
    tenant_id: String,
    upload_path: PathBuf,
}

fn derive_tenant_path(tenant_id: &str) -> PathBuf {
    let mut mac = HmacSha256::new_from_slice(HMAC_SECRET).unwrap();
    mac.update(tenant_id.as_bytes());
    let result = mac.finalize();
    let hash = hex::encode(result.into_bytes());
    PathBuf::from(UPLOAD_ROOT).join(&hash[..16])
}

fn validate_filename(filename: &str) -> Option<String> {
    let path = Path::new(filename);
    let stem = path.file_stem()?.to_str()?;
    let ext = path.extension()?.to_str()?;

    // Block dangerous extensions
    let blocked_exts = ["exe", "sh", "bat", "cmd", "ps1", "php", "jsp", "asp"];
    if blocked_exts.contains(&ext.to_lowercase().as_str()) {
        return None;
    }

    // Sanitize: only allow alphanumeric, dash, underscore in stem
    if !stem.chars().all(|c| c.is_alphanumeric() || c == '-' || c == '_') {
        return None;
    }

    // Validate extension is alphanumeric
    if !ext.chars().all(|c| c.is_alphanumeric()) {
        return None;
    }

    Some(format!("{}.{}", stem, ext))
}

fn resolve_upload_path(tenant_ctx: &TenantContext, filename: &str) -> Option<PathBuf> {
    let safe_name = validate_filename(filename)?;
    let unique_name = format!("{}_{}", Uuid::new_v4().to_string().replace("-", ""), safe_name);
    let full_path = tenant_ctx.upload_path.join(&unique_name);

    // Canonicalize the tenant upload directory
    let canonical_base = std::fs::canonicalize(&tenant_ctx.upload_path).ok()?;

    // Verify the resolved path is within tenant boundary
    // We check that the parent of full_path matches the canonical base
    let parent = full_path.parent()?;

    // Note: we compare the non-canonicalized parent with canonical base
    // This is safe because unique_name has no path separators after validation
    if parent == canonical_base.as_path() {
        Some(full_path)
    } else {
        None
    }
}

async fn extract_tenant(req: &HttpRequest) -> Option<TenantContext> {
    let tenant_id = req.headers().get("X-Tenant-ID")?.to_str().ok()?;

    // Validate tenant ID format
    if tenant_id.len() > 64 || !tenant_id.chars().all(|c| c.is_alphanumeric() || c == '-') {
        return None;
    }

    let upload_path = derive_tenant_path(tenant_id);
    std::fs::create_dir_all(&upload_path).ok()?;

    Some(TenantContext {
        tenant_id: tenant_id.to_string(),
        upload_path,
    })
}

fn check_content_type(data: &[u8], declared_type: &str) -> bool {
    // Verify magic bytes match declared content type
    match declared_type {
        "image/png" => data.starts_with(&[0x89, 0x50, 0x4E, 0x47]),
        "image/jpeg" => data.starts_with(&[0xFF, 0xD8, 0xFF]),
        "image/gif" => data.starts_with(b"GIF8"),
        "application/pdf" => data.starts_with(b"%PDF"),
        "text/plain" => data.iter().all(|&b| b.is_ascii() || b == 0x0A || b == 0x0D),
        _ => true, // Allow other types without magic byte check
    }
}

async fn upload_file(req: HttpRequest, mut payload: Multipart) -> HttpResponse {
    let tenant_ctx = match extract_tenant(&req).await {
        Some(ctx) => ctx,
        None => return HttpResponse::Unauthorized().body("Invalid tenant"),
    };

    let max_size: usize = 10 * 1024 * 1024; // 10MB limit

    while let Some(Ok(mut field)) = payload.next().await {
        let content_disposition = field.content_disposition();
        let filename = match content_disposition.get_filename() {
            Some(f) => f.to_string(),
            None => continue,
        };

        let content_type = field.content_type().map(|m| m.to_string()).unwrap_or_default();

        let dest_path = match resolve_upload_path(&tenant_ctx, &filename) {
            Some(p) => p,
            None => return HttpResponse::BadRequest().body("Invalid filename"),
        };

        let mut file_data: Vec<u8> = Vec::new();
        while let Some(Ok(chunk)) = field.next().await {
            file_data.extend_from_slice(&chunk);
            if file_data.len() > max_size {
                return HttpResponse::PayloadTooLarge().body("File too large");
            }
        }

        if !check_content_type(&file_data, &content_type) {
            return HttpResponse::BadRequest().body("Content type mismatch");
        }

        let mut file = match std::fs::File::create(&dest_path) {
            Ok(f) => f,
            Err(_) => return HttpResponse::InternalServerError().body("Storage error"),
        };

        if file.write_all(&file_data).is_err() {
            return HttpResponse::InternalServerError().body("Write error");
        }

        return HttpResponse::Ok().json(serde_json::json!({
            "status": "uploaded",
            "tenant": tenant_ctx.tenant_id,
            "filename": dest_path.file_name().unwrap().to_str().unwrap()
        }));
    }

    HttpResponse::BadRequest().body("No file provided")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/upload", web::post().to(upload_file))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
